import{_ as e,o as a,c as o,a5 as i}from"./chunks/framework.CcrBcQWS.js";const u=JSON.parse('{"title":"Developer Setup Guide","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"guides/level-0/developers-guide.md","filePath":"guides/level-0/developers-guide.md","lastUpdated":1787021357000}'),s={name:"guides/level-0/developers-guide.md"};function n(r,t,l,d,h,p){return a(),o("div",null,[...t[0]||(t[0]=[i(`<h1 id="developer-setup-guide" tabindex="-1">Developer Setup Guide <a class="header-anchor" href="#developer-setup-guide" aria-label="Permalink to &quot;Developer Setup Guide&quot;">​</a></h1><p><strong>Goal:</strong> Clone the RBQ repository, set up the development environment, and launch the simulator so you can test robot behavior before running on hardware.</p><div class="sb sb-required"><div class="sb-icon"><span class="sb-book" aria-hidden="true">📖</span></div><div class="sb-content"><p class="custom-block-title">REQUIRED READING</p><p>Familiarize yourself with the safety guidelines before testing on the real robot: <a href="/RBQ/nightly/manual/safety/general-safety-warning-precautions">General Safety Guidelines</a>.</p></div></div><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Requirement</th></tr></thead><tbody><tr><td>OS</td><td>Ubuntu 22.04 (x86-64)</td></tr><tr><td>CPU</td><td>Intel Core i7 12th Gen or equivalent</td></tr><tr><td>RAM</td><td>16 GB or more</td></tr><tr><td>Storage</td><td>25 GB free space</td></tr><tr><td>Control</td><td>Keyboard (W/A/S/D/Q/E/R/F, 1–5) or Logitech F710 gamepad</td></tr></tbody></table><h2 id="step-1-clone-the-repository" tabindex="-1">Step 1. Clone the Repository <a class="header-anchor" href="#step-1-clone-the-repository" aria-label="Permalink to &quot;Step 1. Clone the Repository&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RainbowRobotics/RBQ.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ</span></span></code></pre></div><blockquote><p>All SDK source code, examples, scripts, and simulator environments live inside <code>RBQ/</code>.<br> Run all commands from this directory unless stated otherwise.</p></blockquote><blockquote><p><strong>Note:</strong> Pre-built binaries are already included in <code>bin/</code>. No compilation step is required to run the simulator or deploy to the robot.</p></blockquote><h2 id="step-2-launch-the-simulator" tabindex="-1">Step 2. Launch the Simulator <a class="header-anchor" href="#step-2-launch-the-simulator" aria-label="Permalink to &quot;Step 2. Launch the Simulator&quot;">​</a></h2><p>Start the RBQ control stack, MuJoCo physics simulator, and RBQGUI together:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # motion only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # motion + vision sensors</span></span></code></pre></div><p>If prompted, enter your user password in the newly opened terminal windows.</p><h2 id="step-3-connect-and-initialize-in-rbqgui" tabindex="-1">Step 3. Connect and Initialize in RBQGUI <a class="header-anchor" href="#step-3-connect-and-initialize-in-rbqgui" aria-label="Permalink to &quot;Step 3. Connect and Initialize in RBQGUI&quot;">​</a></h2><ol><li>In RBQGUI, click <strong>Connect</strong> — the indicator changes to <strong>Simulator Connected</strong> (blue).</li><li>Click <strong>Auto Start Robot</strong> — all indicators turn green when ready.</li><li>In the <strong>Walk</strong> tab, press <strong>Stance</strong> (or keyboard <code>2</code>) to stand the robot up.</li></ol><p>The robot is now ready to receive commands. Refer to <a href="/RBQ/nightly/guides/common/basic-motion-command.html">Basic Motion Command</a> for joystick and gait control.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>In simulation, only <strong>Control Start</strong> turns green. On the real robot, all three startup indicators (Motor Check / Initialize Pose / Control Start) turn green when ready.</p></div></div><h2 id="step-4-run-on-the-real-robot" tabindex="-1">Step 4. Run on the Real Robot <a class="header-anchor" href="#step-4-run-on-the-real-robot" aria-label="Permalink to &quot;Step 4. Run on the Real Robot&quot;">​</a></h2><p>When you are ready to test on hardware:</p><ol><li>Place the robot in the <a href="/RBQ/nightly/guides/common/initial-pose.html">correct initial pose</a>.</li><li>Connect your development PC to the robot Wi-Fi (<code>RBQ_xxxx</code>).</li><li>Launch the GUI (from <code>RBQ/</code>):</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/GUI</span></span></code></pre></div><ol start="4"><li>Click <strong>Connect</strong> → <strong>Auto Start Robot</strong> → <strong>Stance</strong>.</li></ol><blockquote><p>It is strongly recommended to verify all behaviors in simulation before testing on the real robot.</p></blockquote><h2 id="step-5-update-the-robot" tabindex="-1">Step 5. Update the Robot <a class="header-anchor" href="#step-5-update-the-robot" aria-label="Permalink to &quot;Step 5. Update the Robot&quot;">​</a></h2><p>Robot software is updated from RBQGUI, using <strong><code>UPDATE ROBOT</code></strong> on the <code>Software Update</code> screen. RBQGUI transfers and installs the new version, then prompts you to restart.</p><p><strong>→ <a href="/RBQ/nightly/manual/gui/robot-software-update.html">Robot Software Update</a></strong></p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Put the robot in the <strong>sitting</strong> state before restarting, and do not move it until the restart finishes. Running a mismatched binary and script combination can cause unexpected behavior.</p></div></div><h2 id="detailed-reference" tabindex="-1">Detailed Reference <a class="header-anchor" href="#detailed-reference" aria-label="Permalink to &quot;Detailed Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Link</th></tr></thead><tbody><tr><td>Full GUI walkthrough</td><td><a href="/RBQ/nightly/software/developers-guide.html">Developers Guide (Software)</a></td></tr><tr><td>GUI panel details</td><td><a href="/RBQ/nightly/manual/gui/introduction.html">GUI Introduction</a></td></tr><tr><td>Simulation environment</td><td><a href="/RBQ/nightly/software/developers-guide.html#simulation">MuJoCo Simulation</a></td></tr><tr><td>Concepts &amp; architecture</td><td><a href="/RBQ/nightly/software/concept.html">Concept</a></td></tr></tbody></table>`,29)])])}const b=e(s,[["render",n]]);export{u as __pageData,b as default};
